// font-display.ts: self-hosted display typeface for the marketing hero.
//
// Roboto Slab Bold (Apache License 2.0, Google Fonts; redistributable), shipped
// as a base64 woff2 data: URI so the page stays ZERO-EGRESS / air-gap renderable
// (a data: URI is inline, not a remote fetch, so the offline-smoke gate passes
// and the byte output is deterministic). A slab serif reads as durable, owned,
// engineered infrastructure, the opposite of the generic teal SaaS sans this
// brand explicitly rejects. Body + UI text stay on the system sans stack (no
// second bundled face), so only ONE woff2 is inlined: spent on the headline,
// section titles, brand, and stat numerals where the display voice earns its
// bytes. The literal is a single trusted constant (no authored input, no
// dashes), consumed only inside an @font-face src in the inlined <style>.
export const DISPLAY_FONT_WOFF2_BASE64 ='';

/** data: URI for the @font-face src (woff2). */
export const DISPLAY_FONT_DATA_URI = `data:font/woff2;base64,${DISPLAY_FONT_WOFF2_BASE64}`;

/** Family name used by the @font-face and the --font-display token. */
export const DISPLAY_FONT_FAMILY = "CuraOS Slab";
